('cf3f6432-11ae-5e19-8a7b-6b5cdbf3bb57'::uuid, 'f957b0fc-b812-5e34-9a27-342f30f56922'::uuid, 'fgd', 'verbal'::public.evidence_strength, 'CDRRMO field self-assessment (FGD), October 2026', 'CDRRMO section FGDs', 'no EO or ordinance on ICS.'),
