('70274f5b-6e80-53df-a650-0d33b02b0d36'::uuid, '0fa90af3-ab44-5839-91be-b68ea704aad4'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '10-Yr Plan says response cluster offices are assigned; institutionalisation planned. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('70d09e9c-8322-5dc6-9cc0-a6e0dc13e7e3'::uuid, '0fa90af3-ab44-5839-91be-b68ea704aad4'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) CDP 2024-2030 Table 17 programme 3.0 sets response support programmes by function (EOC and ICS, emergency telecoms, logistics, MDM, SRR, CCCM, education, FNFI, health, temporary resettlement, lifelines), matching the cluster approach; cluster lead offices sit on the CDRRMC (EO 2024-032A). [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('d24506d4-abdd-5c33-b96d-c2261d0c1bb1'::uuid, '0fa90af3-ab44-5839-91be-b68ea704aad4'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(issuances 2021-2024, read 6 Nov 2026) EO s.2022 (filed as EO 263; the scan reads "243", check the number) organises the City CCCM Team under the CDRRMC Response Cluster, led by the CSWDO, with CDRRMO, CHD, Police, Engineering, GSO, Housing, Legal, DepEd, Liga, Red Cross, an NGO and a civic group; its functions cover EC availability, temporary refuge, basic needs, 24/7 health services, animal areas and transition to recovery. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('37570401-cd31-50c6-b27d-4fffb6614cde'::uuid, '0fa90af3-ab44-5839-91be-b68ea704aad4'::uuid, 'observation', 'approved_in_use'::public.evidence_strength, 'Site observation, October 2026', 'Assessment team site visit', '(Oct 2026 site visit) camp coordination and management arrangements were observed at the evacuation site in Brgy. Liloan. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('c39b00bb-24c9-5abe-998a-ca1fa050ec5f'::uuid, '66ede178-35b1-5e4c-ade4-46fd27bb5959'::uuid, 'fgd', 'verbal'::public.evidence_strength, 'CDRRMO field self-assessment (FGD), October 2026', 'CDRRMO section FGDs', 'scored 3.'),
