('60c40014-8322-5c3b-8b48-b76ceade1e0f'::uuid, '8a64d65d-181f-5c3a-af70-ee88f8850e6f'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) CDP PPAs 3.6 (MDM response support) and 4.2 (PDNA capacity building and conduct) are planned; no team designation in the set.'),
('f91a7993-e5e1-5b06-9295-a226d84656f3'::uuid, '8a64d65d-181f-5c3a-af70-ee88f8850e6f'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(issuances 2021-2024, read 6 Nov 2026) CDRRMC Res. 06 s.2021 (29 Sep 2021) approved the MDM Cluster protocol for deaths from COVID-19; Allotment Release Order 381 (2021) released MOOE for disease control and MDM operations. Score 1 -> 2: an approved, used MDM protocol exists, but it covers COVID-19 only; no all-hazards MDM team or RDANA team is designated.'),
('fb1b241c-9129-5bbf-8fcc-8ac4586c7c87'::uuid, '90f53e13-3442-5cac-8251-da67c040775e'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', 'PDRA practised (A8.6), CPs exist, but no hazard/lead-time AA protocol or office-order template found.'),
('dcfd51a2-04ef-5f47-a595-42fb501bb6c5'::uuid, 'de94f78b-8f9b-544b-9ee5-a2f74ea3f2c3'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', 'CBMS needs updating; no DSA for beneficiary data (A5.5).'),
('0f83efc9-a5ce-52af-92ca-b263a3ed1368'::uuid, '0779c1ad-3d7c-5200-94d9-698867888082'::uuid, 'fgd', 'verbal'::public.evidence_strength, 'CDRRMO field self-assessment (FGD), October 2026', 'CDRRMO section FGDs', 'PDNA team not in place.'),
('5b1259e2-7478-5613-b1cc-4b90327631fa'::uuid, '0779c1ad-3d7c-5200-94d9-698867888082'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '10-Yr Plan plans 5 PDNA positions (2025).'),
