('263a9fd8-acc1-5962-ad95-bb83725e1d04'::uuid, '40ceca04-5ca2-5e21-91f5-820d960a5a59'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '10-Yr Plan says EOC operations need institutionalising through a manual/SOP. | Manual Development is on going'),
